<template>
  <v-theme-provider theme="light">
    <div class="editor-wrapper" style="border: black solid 2px; border-radius: 5px;" v-if="editor && editor.isEditable && isActive">
      <div class="d-flex justify-center flex-wrap pb-2 pt-1" id="buttons">
        <v-defaults-provider :defaults="defaults">
        <v-btn
          title="Bold"
          v-bind="activeButtonProps(editor.isActive('bold'))"
          @click="editor.chain().focus().toggleBold().run()"
        >
          <v-icon>mdi-format-bold</v-icon>
        </v-btn>
        <v-btn
          title="Italic"
          v-bind="activeButtonProps(editor.isActive('italic'))"
          @click="editor.chain().focus().toggleItalic().run()"
        >
          <v-icon>mdi-format-italic</v-icon>
        </v-btn>
          <ColorMenu v-if="!limitedEditing" :editor="editor" />
          <v-btn
            title="Disclaimer style"
            v-if="!limitedEditing"
            v-bind="activeButtonProps(editor.isActive('strike'))"
            @click="editor.chain().focus().toggleStrike().run()"
          >
            <v-icon>mdi-size-xs</v-icon>
          </v-btn>
          <LinkMenu :editor="editor" />
          <v-btn title="Subscript" v-bind="activeButtonProps(editor.isActive('subscript'))" @click="editor.chain().focus().toggleSubscript().run()">
            <v-icon>mdi-format-subscript</v-icon>
          </v-btn>
          <v-btn title="Superscript" v-bind="activeButtonProps(editor.isActive('superscript'))" @click="editor.chain().focus().toggleSuperscript().run()">
            <v-icon>mdi-format-superscript</v-icon>
          </v-btn>
          <div class="d-flex justify-center flex-wrap">
            <v-btn v-if="!limitedEditing" title="Align Left"  v-bind="activeButtonProps(editor.isActive({ textAlign: 'left' }))" @click="editor.chain().focus().setTextAlign('left').run()">
              <v-icon>mdi-format-align-left</v-icon>
            </v-btn>
            <v-btn v-if="!limitedEditing" title="Align Center" v-bind="activeButtonProps(editor.isActive({ textAlign: 'center' }))" @click="editor.chain().focus().setTextAlign('center').run()">
              <v-icon>mdi-format-align-center</v-icon>
            </v-btn>
            <v-btn v-if="!limitedEditing" title="Align Center" v-bind="activeButtonProps(editor.isActive({ textAlign: 'right' }))" @click="editor.chain().focus().setTextAlign('right').run()">
              <v-icon>mdi-format-align-right</v-icon>
            </v-btn>
            <v-btn title="Undo" @click="editor.chain().focus().undo().run()">
              <v-icon>mdi-undo</v-icon>
            </v-btn>
            <v-btn title="Redo" @click="editor.chain().focus().redo().run()">
              <v-icon>mdi-redo</v-icon>
            </v-btn>
          </div>
        </v-defaults-provider>
      </div>
      <editor-content class="pb-2 px-2" :editor="editor"/>
    </div>
    <div v-else v-html="editor?.getHTML()"/>
  </v-theme-provider>
</template>

<script>
import {Editor, EditorContent, Extension} from '@tiptap/vue-3';
import Italic from '@tiptap/extension-italic';
import StarterKit from '@tiptap/starter-kit';
import Document from '@tiptap/extension-document';
import Text from '@tiptap/extension-text';
import Subscript from '@tiptap/extension-subscript';
import Superscript from '@tiptap/extension-superscript';
import Highlight from '@tiptap/extension-highlight';
import TextAlign from '@tiptap/extension-text-align';
import TextStyle from '@tiptap/extension-text-style';
import {HardBreak} from "@tiptap/extension-hard-break";
import Strike from "@tiptap/extension-strike";
import {defineComponent} from "vue";
import {Paragraph} from "@tiptap/extension-paragraph";
import {Typography} from "@tiptap/extension-typography";
import LinkMenu, { CustomLink, StyledLink } from '@/components/text/LinkMenu.vue';
import { LinkValidationExtension } from '@/components/text/LinkValidationExtension.js';
import ColorMenu from '@/components/text/ColorMenu.vue';
import { normalizeColor } from '@/utils/textColor';

export default defineComponent({
  components: {
    EditorContent,
    LinkMenu,
    ColorMenu,
  },
  props: {
    modelValue: {
      type: [String, Object],
      default: '',
    },
    isActive: {
      type: Boolean,
      default: false,
    },
    backgroundColor: {
      type: String,
    },
    limitedEditing: {
      type: Boolean,
      default: false,
    },
    insideSmallElement: {
      type: Boolean,
      default: false,
    }
  },
  emits: ['update:modelValue'],
  data() {
    return {
      defaults: {
        VBtn: {
          variant: 'text',
          size: this.insideSmallElement ? 'small' : 'default',
        }
      },
      editor: null,
    }
  },

  watch: {
    modelValue(value) {
      // Legacy content is stored as an HTML string; new content is TipTap JSON.
      const isSame = typeof value === 'string'
        ? this.editor.getHTML() === value
        : JSON.stringify(this.editor.getJSON()) === JSON.stringify(value)

      if (isSame) {
        return
      }

      this.editor.commands.setContent(value, false);
    },
  },
  mounted() {
    const CustomItalic = Italic.extend({
      renderHTML({HTMLAttributes}) {
        return ['i', HTMLAttributes, 0]
      }
    });
    const DISCLAIMER_STYLE =
      'font-family:Roboto,sans-serif;font-size:14px;line-height:22px;color:var(--disclaimer-color,#785f5f);padding:20px 0;';

    const isDisclaimerElement = element => {
      const style = (element.getAttribute('style') || '')
        .toLowerCase()
        .replace(/\s/g, '');

      return (
        element.getAttribute('data-disclaimer') === 'true' ||
        (
          style.includes('font-size:14px') &&
          style.includes('line-height:22px') &&
          (
            style.includes('color:#785f5f') ||
            style.includes('color:rgb(120,95,95)')
          )
        )
      );
    };

    const CustomStrike = Strike.extend({
      parseHTML() {
        return [
          {
            tag: 'span[data-disclaimer="true"]',
          },
          {
            tag: 'span',
            getAttrs: element => isDisclaimerElement(element) ? {} : false,
          },
        ];
      },

      renderHTML({ HTMLAttributes }) {
        return [
          'span',
          {
            ...HTMLAttributes,
            'data-disclaimer': 'true',
            style: DISCLAIMER_STYLE,
          },
          0,
        ];
      },
    });
    /*const CustomHighlight = Highlight.extend({
      renderHTML({HTMLAttributes}) {
        return ['em', HTMLAttributes, 0]
      }
    })*/
    this.editor = new Editor({
      extensions: [
        StarterKit,
        CustomItalic,
        Document,
        Paragraph,
        Text,
        Subscript,
        Superscript,
        Highlight,
        CustomStrike,
        CustomLink,
        StyledLink,
        LinkValidationExtension,
        TextStyle,
        Typography.configure({
          openDoubleQuote: "„",
          closeDoubleQuote: "“",
          openSingleQuote: "'",
          closeSingleQuote: "'",
        }),
        HardBreak.extend({
          addKeyboardShortcuts() {
            return {
              Enter: () => this.editor.commands.setHardBreak()
            }
          }
        }),
        // color example: https://codesandbox.io/s/cz6ro?file=/src/App.vue
        Color,
        TextAlign.configure({
          types: ['heading', 'paragraph'],
        }),
      ],
      content: this.modelValue,
      editorProps: {
        // This section fixes line breaks when pasting text from MS Word.
        handlePaste: (view, event) => {
          const plainText = event.clipboardData?.getData('text/plain')

          if (!plainText) {
            return false
          }

          const normalizedText = plainText
            .replace(/\r\n/g, '\n')
            .replace(/\r/g, '\n')

          // Let TipTap handle normal single-line paste.
          if (!normalizedText.includes('\n')) {
            return false
          }

          event.preventDefault()

          const content = []

          const lines = normalizedText.split('\n')

          lines.forEach((line, index) => {
            if (line.length > 0) {
              content.push({
                type: 'text',
                text: line,
              })
            }

            // Every pasted newline becomes the same thing as pressing Enter
            // in your editor: a hardBreak.
            if (index < lines.length - 1) {
              content.push({
                type: 'hardBreak',
              })
            }
          })

          this.editor
            .chain()
            .focus()
            .insertContent(content)
            .run()

          return true
        },

        // This section fixes 2 things about pasting text from MS Word. It does this by just removing textStyles entirely, things like bold, italic, sub/superscript etc. still work.
        // 1) removing empty spans from pasted content
        // 2) getting rid of <span style="color: [object Object]"> that would often happen, especially when the copied text was colored.
        transformPasted(text) {
          for (const item of text.content.content) {
            if (item.marks) item.marks = item.marks.filter(x => x.type.name !== "textStyle");
            for (const content of item.content.content) {
              if (content.marks) content.marks = content.marks.filter(x => x.type.name !== "textStyle");
            }
          }
          return text;
        },
      },
      onUpdate: () => {
        // HTML
        // this.$emit('update:modelValue', this.editor.getHTML());

        // JSON
        this.$emit('update:modelValue', this.editor.getJSON())
      },
    })
  },
  methods: {
    activeButtonProps(active) {
      return {
        color: active ? 'black' : undefined,
        variant: active ? 'flat' : 'text',
        ripple: false,
      };
    },
  },

  beforeUnmount() {
    this.editor.destroy()
  },
})

export const Color = Extension.create({
  name: "color",

  addOptions: {
    types: ["textStyle"]
  },

  addGlobalAttributes() {
    return [
      {
        types: this.options.types,
        attributes: {
          color: {
            default: null,
            renderHTML: (attributes) => {
              const color = normalizeColor(attributes.color);
              if (!color) {
                return {};
              }
              return {
                style: `color: ${color}`
              };
            },
            parseHTML: (element) => {
              const color = normalizeColor(element.style.color);
              if (!color) {
                return {};
              }
              return { color };
            }
          },
          colorId: {
            default: null,
            renderHTML: () => ({}),
            parseHTML: () => null,
          }
        }
      }
    ];
  },
});

</script>

<style lang="scss" scoped>
/* Basic editor styles */
.ProseMirror {
  > * + * {
    margin-top: 0.75em;
  }

  ul,
  ol {
    padding: 0 1rem;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    line-height: 1.1;
  }

  code {
    background-color: rgba(#616161, 0.1);
    color: #616161;
  }

  pre {
    background: #0D0D0D;
    color: #FFF;
    font-family: 'JetBrainsMono', monospace;
    padding: 0.75rem 1rem;
    border-radius: 0.5rem;

    code {
      color: inherit;
      padding: 0;
      background: none;
      font-size: 0.8rem;
    }
  }

  img {
    max-width: 100%;
    height: auto;
  }

  blockquote {
    padding-left: 1rem;
    border-left: 2px solid rgba(#0D0D0D, 0.1);
  }

  hr {
    border: none;
    border-top: 2px solid rgba(#0D0D0D, 0.1);
    margin: 2rem 0;
  }
}

#buttons {
  border-bottom: 2px solid black;
  margin: 5px 0 10px 0;
}

:deep(a.invalid-link-highlight),
:deep(.invalid-link-highlight) {
  text-decoration-line: underline !important;
  text-decoration-style: wavy !important;
  text-decoration-color: #d32f2f !important;
  text-decoration-thickness: 2px !important;
  text-underline-offset: 3px;
}

</style>
