import { Extension } from '@tiptap/vue-3'
import { Plugin, PluginKey } from '@tiptap/pm/state'
import { Decoration, DecorationSet } from '@tiptap/pm/view'
import { isValidUrl } from '@/utils/helpers.ts';

function normalizeHref(href) {
  if (typeof href === 'string') return href
  if (href == null) return ''
  return String(href)
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())
}

function looksLikePhoneNumber(value) {
  return /^\+?[\d\s()-]+$/.test(value.trim())
}

function isInvalidLinkHref(href) {
  const value = normalizeHref(href).trim()

  if (!value) {
    return true
  }

  if (value.startsWith('tel:')) {
    const phone = value.replace(/^tel:/i, '')
    return !looksLikePhoneNumber(phone)
  }

  if (value.startsWith('mailto:')) {
    const email = value.replace(/^mailto:/i, '')
    return !isValidEmail(email)
  }

  if (isValidEmail(value)) {
    return true
  }

  if (looksLikePhoneNumber(value)) {
    return true
  }

  if (!isValidUrl(value)) {
    return true
  }

  return false
}

export const LinkValidationExtension = Extension.create({
  name: 'linkValidation',

  addProseMirrorPlugins() {
    return [
      new Plugin({
        key: new PluginKey('linkValidation'),

        props: {
          decorations(state) {
            const decorations = []
            const linkType = state.schema.marks.link

            if (!linkType) {
              return DecorationSet.empty
            }

            state.doc.descendants((node, pos) => {
              if (!node.isText) {
                return
              }

              const linkMark = node.marks.find(mark => mark.type === linkType)

              if (!linkMark) {
                return
              }

              const href = linkMark.attrs.href

              if (!isInvalidLinkHref(href)) {
                return
              }

              let error = 'Invalid link';
              if (href.startsWith('tel:')) {
                error = 'Invalid phone number'
              } else if (href.startsWith('mailto:')) {
                error = 'Invalid email address'
              }

              decorations.push(
                Decoration.inline(pos, pos + node.nodeSize, {
                  class: 'invalid-link-highlight',
                  title: error,
                })
              )
            })

            return DecorationSet.create(state.doc, decorations)
          },
        },
      }),
    ]
  },
})