import { Editor, Extension, JSONContent } from '@tiptap/core';
import StarterKit from '@tiptap/starter-kit';
import Document from '@tiptap/extension-document';
import Paragraph from '@tiptap/extension-paragraph';
import Text from '@tiptap/extension-text';
import Italic from '@tiptap/extension-italic';
import Strike from '@tiptap/extension-strike';
import Subscript from '@tiptap/extension-subscript';
import Superscript from '@tiptap/extension-superscript';
import Highlight from '@tiptap/extension-highlight';
import TextAlign from '@tiptap/extension-text-align';
import TextStyle from '@tiptap/extension-text-style';
import HardBreak from '@tiptap/extension-hard-break';
import Link from '@tiptap/extension-link';
import TipTap from '@/types/TipTap';
import { normalizeColor } from '@/utils/textColor';

const DISCLAIMER_STYLE =
  'font-family:Roboto,sans-serif;font-size:14px;line-height:22px;color:var(--disclaimer-color,#785f5f);padding:20px 0;';

const Color = Extension.create({
  name: 'color',

  addOptions() {
    return { types: ['textStyle'] };
  },

  addGlobalAttributes() {
    return [
      {
        types: this.options.types,
        attributes: {
          color: {
            default: null,
            renderHTML: (attributes: { color?: unknown }) => {
              const color = normalizeColor(attributes.color);
              if (!color) return {};
              return { style: `color: ${color}` };
            },
          },
        },
      },
    ];
  },
});

const CustomItalic = Italic.extend({
  renderHTML({ HTMLAttributes }) {
    return ['i', HTMLAttributes, 0];
  },
});

const DisclaimerStrike = Strike.extend({
  renderHTML({ HTMLAttributes }) {
    return ['span', { ...HTMLAttributes, 'data-disclaimer': 'true', style: DISCLAIMER_STYLE }, 0];
  },
});

const EmailLink = Link.extend({
  addOptions() {
    return {
      ...this.parent?.(),
      openOnClick: false,
      HTMLAttributes: { target: '_blank', class: null },
    };
  },
});

const StyledLink = Extension.create({
  name: 'styledLink',

  addOptions() {
    return { types: ['link'] };
  },

  addGlobalAttributes() {
    return [
      {
        types: this.options.types,
        attributes: {
          color: {
            default: null,
            renderHTML: () => ({
              style: 'font-family:Roboto,sans-serif;color:#257886 !important;--disclaimer-color:#257886;text-decoration:underline;',
            }),
          },
        },
      },
    ];
  },
});

function getExtensions() {
  return [
    StarterKit,
    CustomItalic,
    Document,
    Paragraph,
    Text,
    Subscript,
    Superscript,
    Highlight,
    DisclaimerStrike,
    EmailLink,
    StyledLink,
    TextStyle,
    HardBreak,
    Color,
    TextAlign.configure({
      types: ['heading', 'paragraph'],
    }),
  ];
}

/**
 * Renders a TextEditor field (TipTap JSON, or a legacy HTML string) to an HTML string
 * for use in the generated email. Legacy string content is already HTML and passes through.
 */
export default function getTextHtml(content: unknown): string {
  if (!content) return '';
  if (typeof content === 'string') return content;

  const editor = new Editor({
    extensions: getExtensions(),
    content: content as JSONContent,
  });

  const html = editor.getHTML();

  editor.destroy();

  return html;
}

/**
 * Whether a TextEditor field (JSON or legacy HTML string) has no meaningful content.
 */
export function isTextEditorContentEmpty(content: unknown): boolean {
  if (!content) return true;
  if (typeof content === 'string') return content === '' || content === '<p></p>';

  const doc = content as TipTap;

  if (!doc.content || doc.content.length === 0) return true;

  return doc.content.every(node => !node.content || node.content.length === 0);
}
